<script>
  // Mock "track"
  const track = {
    title: "Sacrifice",
    artist: "Mariah the Scientist — HEARTS SOLD SEPARATELY",
    duration: 95  // seconds
  };

  // State
  const state = { playing:false, t:0, duration:track.duration, tick:null };

  // Elements
  const overlay = document.getElementById('overlay');
  const mini = document.getElementById('miniPlayer');
  const closeOverlay = document.getElementById('closeOverlay');

  const miniFill = document.getElementById('miniFill');
  const topFill = document.getElementById('topFill');
  const bottomFill = document.getElementById('bottomFill');

  const curTime = document.getElementById('curTime');
  const remainTime = document.getElementById('remainTime');

  const playBtn = document.getElementById('playPauseBtn');
  const playIcon = document.getElementById('playIcon');
  const ovPlayBtn = document.getElementById('ovPlayPause');
  const ovPlayIcon = document.getElementById('ovPlayIcon');

  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');
  const ovPrev = document.getElementById('ovPrev');
  const ovNext = document.getElementById('ovNext');

  // Init UI
  document.getElementById('miniTitle').textContent = track.title;
  document.getElementById('miniArtist').textContent = track.artist;
  document.getElementById('ovTitle').textContent = track.title;
  document.getElementById('ovArtist').textContent = track.artist;
  updateTime();

  function fmt(s){
    s = Math.max(0, Math.floor(s));
    const m = Math.floor(s/60);
    const r = s%60;
    return m + ":" + (r<10 ? "0"+r : r);
  }
  function updateTime(){
    const p = state.t / state.duration;
    miniFill.style.width = (p*100)+"%";
    topFill.style.width = (p*100)+"%";
    bottomFill.style.width = (p*100)+"%";
    curTime.textContent = fmt(state.t);
    remainTime.textContent = "-" + fmt(state.duration - state.t);
  }
  function startTick(){
    if(state.tick) return;
    state.tick = setInterval(()=>{
      if(!state.playing) return;
      state.t += 0.25;
      if(state.t >= state.duration){
        state.t = 0; state.playing = false; swapPlayIcons();
        clearInterval(state.tick); state.tick = null;
      }
      updateTime();
    },250);
  }
  function swapPlayIcons(){
    if(state.playing){
      playIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg";
      ovPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg";
    }else{
      playIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg";
      ovPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg";
    }
  }

  function togglePlay(){
    state.playing = !state.playing;
    swapPlayIcons();
    startTick();
  }

  // Controls
  playBtn.addEventListener('click', togglePlay);
  ovPlayBtn.addEventListener('click', togglePlay);

  function prev(){
    state.t = Math.max(0, state.t - 10);
    updateTime();
  }
  function next(){
    state.t = Math.min(state.duration, state.t + 10);
    updateTime();
  }
  prevBtn.addEventListener('click', prev);
  nextBtn.addEventListener('click', next);
  ovPrev.addEventListener('click', prev);
  ovNext.addEventListener('click', next);

  // Open/Close overlay
  mini.addEventListener('click', ()=> overlay.classList.add('show'));
  closeOverlay.addEventListener('click', ()=> overlay.classList.remove('show'));

  // Seek on bars
  function seekFromBar(e, barEl){
    const rect = barEl.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const p = Math.max(0, Math.min(1, x / rect.width));
    state.t = state.duration * p;
    updateTime();
  }
  document.getElementById('topBar').addEventListener('click', (e)=>seekFromBar(e,e.currentTarget));
  document.getElementById('bottomBar').addEventListener('click', (e)=>seekFromBar(e,e.currentTarget));

  // Make sidebar items clickable highlight
  document.querySelectorAll('.nav .item').forEach(it=>{
    it.addEventListener('click', ()=>{
      document.querySelectorAll('.nav .item').forEach(x=>x.classList.remove('active'));
      it.classList.add('active');
    });
  });

  // Ensure ticking stops when page hidden
  document.addEventListener('visibilitychange', ()=>{
    if(document.hidden){ /* keep state, no-op */ }
  });

  // Start paused but show UI moving when play clicked
  updateTime();
</script>
</body>
